const completeDesignNames=['Marketplace Index','Skills Hub','MCP Market','Technical Registry','AI Templates','Inference Utility','Open Intelligence'];const previousBrandShell=shell;shell=function(){previousBrandShell();const header=$('.topbar')||$('.template-top');header.insertAdjacentHTML('beforeend','<label class="header-design-switch"><span>Design</span><select aria-label="Switch website design" id="headerDesign">'+completeDesignNames.map((n,i)=>'<option value="'+(i+1)+'" '+(V===i+1?'selected':'')+'>0'+(i+1)+' · '+n+'</option>').join('')+'</select></label>');const switchDesign=value=>{const target=new URL(window.MERGED_BRAND?location.href:'index.html',location.href);target.searchParams.set('design',value);target.hash=location.hash||'#/discover';location.href=target.href;};$('#headerDesign').onchange=e=>switchDesign(e.target.value);if($('#design'))$('#design').onchange=e=>switchDesign(e.target.value);document.body.classList.add('brand-refined');};
const shellBeforeThemeButton=shell;shell=function(){shellBeforeThemeButton();const header=$('.topbar')||$('.template-top');let button=$('#themeToggle');if(!button){button=document.createElement('button');button.id='themeToggle';}button.className='header-theme-toggle';header.append(button);const storageKey='brand-colour-theme-'+B.id;const moon='<svg class="vector-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M20.5 14.2A8.5 8.5 0 0 1 9.8 3.5a8.5 8.5 0 1 0 10.7 10.7Z"/></svg>';const sync=()=>{const dark=document.body.dataset.theme==='dark';button.innerHTML=dark?svgIcon('sun'):moon;button.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');button.title=dark?'Switch to light mode':'Switch to dark mode';button.setAttribute('aria-pressed',String(dark));if($('#theme'))$('#theme').value=document.body.dataset.theme;};window.restoreBrandColourTheme=()=>{try{const saved=localStorage.getItem(storageKey);if(['light','dark','contrast'].includes(saved))document.body.dataset.theme=saved;}catch{}sync();};button.onclick=()=>{const next=document.body.dataset.theme==='dark'?'light':'dark';document.body.dataset.theme=next;try{localStorage.setItem(storageKey,next);}catch{}sync();};const select=$('#theme');if(select){const oldChange=select.onchange;select.onchange=e=>{oldChange?.call(select,e);document.body.dataset.theme=e.target.value;try{localStorage.setItem(storageKey,e.target.value);}catch{}sync();};}new MutationObserver(sync).observe(document.body,{attributes:true,attributeFilter:['data-theme']});window.restoreBrandColourTheme();};
